package dev.codex.lastzhelper;
import android.content.*;import android.media.*;import android.os.*;import java.io.*;import java.util.concurrent.*;import org.json.*;
final class JobRunner {
 interface Listener{void update(String state,String detail,boolean busy);}
 static final CopyOnWriteArrayList<Listener> listeners=new CopyOnWriteArrayList<>();static final Handler main=new Handler(Looper.getMainLooper());
 static volatile boolean busy=false;static volatile String state="Ready",detail="Open the intended game and choose a mode from floating controls.",summary="Trucks/bounties use the active game; maintenance visits selected games.";
 static void publish(String s,String d){state=s;detail=d;summary=d;main.post(()->{for(Listener l:listeners)l.update(state,detail,busy);});}
 static String q(String s){return "'"+s.replace("'","'\\''")+"'";}
 static boolean recovered;
 static synchronized void recover(Context c){if(recovered)return;recovered=true;File f=new File(c.getFilesDir(),"rotation-progress.json");if(!f.exists())return;try{JSONObject p=new JSONObject(StateProbe.text(f.getPath()));if(p.optBoolean("running"))publish("Interrupted","Previous rotation ended without a final checkpoint. No job was restarted. Select games and press Run when ready; pending attempts remain protected.");}catch(Exception e){publish("Needs attention","Cannot read previous rotation status: "+e.getMessage());}}
 static JSONObject options(Context c){android.content.SharedPreferences p=c.getSharedPreferences("runs",0);try{return new JSONObject().put("start",p.getInt("start",17)).put("end",p.getInt("end",64)).put("resume",true).put("maxRefreshes",-1).put("skipTruckState",p.getInt("skipTruckState",0)).put("attackPowerM",p.getInt("attackPowerM",440)).put("dryRun",p.getBoolean("dry",true)).put("shareDestination",p.getString("shareDestination",ShareDestination.WORLD));}catch(Exception e){throw new IllegalStateException(e);}}
 static File asset(Context c,String name,String dest,boolean replace)throws Exception{
  File f=new File(c.getFilesDir(),dest);if(replace||!f.exists()){File t=new File(f.getPath()+".new");try(InputStream in=c.getAssets().open(name);OutputStream out=new FileOutputStream(t)){byte[] b=new byte[1048576];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}if(!t.renameTo(f)){if(f.exists()&&!f.delete())throw new IOException("Cannot replace asset");if(!t.renameTo(f))throw new IOException("Cannot install asset");}}
  return f;
 }
 static File prepare(Context c)throws Exception{
  boolean arm=false,x86=false;for(String abi:Build.SUPPORTED_ABIS){arm|=abi.equals("arm64-v8a");x86|=abi.equals("x86_64");}
  if(!arm&&!x86)throw new IOException("A 64-bit ARM or x86 Android device is required");
  asset(c,arm?"injector-arm64.dat":"injector.dat",arm?"injector-arm64-17.24.3":"injector-17.24.3",false).setExecutable(true,true);
  String agentName;try(InputStream source=c.getAssets().open("input-agent.js")){agentName=RuntimeAssetIdentity.agentName(source);}File agent=asset(c,"input-agent.js",agentName,false);try(InputStream existing=new FileInputStream(agent)){if(!agentName.equals(RuntimeAssetIdentity.agentName(existing)))throw new IOException("Cached agent content does not match its immutable identity");}
  File ledger=new File(c.getFilesDir(),"world-shares.json");if(!ledger.exists())asset(c,"initial-shares.json","world-shares.json",false);return agent;
 }
 static synchronized void start(Context context,String requestedMode,JSONObject options){startInternal(context,requestedMode,options,false);}
 static synchronized void resume(Context context){if(busy)return;try{RunRequest r=new RunRequest(context.getFilesDir());JSONObject saved=r.read();File stop=new File(context.getFilesDir(),"stop-request");if(saved!=null&&r.active(saved.getString("generation"),stop))startInternal(context,"maintenance-rotation",saved.getJSONObject("options"),true);}catch(Exception e){publish("Needs attention","Cannot recover previous bot session: "+e.getMessage());}}
 static synchronized void startInternal(Context context,String requestedMode,JSONObject supplied,boolean recovering){
  if(busy)return;Context c=context.getApplicationContext();final JSONObject options;final String mode;final boolean bot;final RunRequest request=new RunRequest(c.getFilesDir());final String generation;File globalStop=new File(c.getFilesDir(),"stop-request");
  try{options=new JSONObject(supplied.toString());mode=ShareDestination.resolve(requestedMode,options.optString("shareDestination",ShareDestination.WORLD));bot=mode.equals("maintenance-rotation");
   if(bot&&!options.has("selectedProfiles")){JSONObject saved=BotRun.options(c,options.optBoolean("dryRun",true));options.put("selectedProfiles",saved.getJSONArray("selectedProfiles"));}
   if(recovering){generation=options.getString("runGeneration");if(!request.restart(generation,globalStop))throw new IOException("Worker restart limit reached or run cancelled");options.put("restartingWorker",true);}else{if(globalStop.exists()&&!globalStop.delete())throw new IOException("Cannot clear old STOP request");generation=bot?request.begin(options):"";}
  }catch(Exception e){publish("Needs attention",e.getMessage());return;}
  busy=true;publish(recovering?"Recovering":"Preparing",recovering?"Recovering the requested bot session; verifying account and pending operations.":"Preparing "+mode+". STOP is available in the notification.");
  new Thread(()->{java.lang.Process p=null;RunAwake awake=null;int code=-1;JSONObject last=null;StringBuilder text=new StringBuilder();boolean forcedAbort=false;
   try{awake=new RunAwake(c,6*60*60*1000L);File agent=prepare(c),cache=new File(c.getFilesDir(),"probe-cache.txt");String prefix="CLASSPATH="+q(c.getApplicationInfo().sourceDir)+" /system/bin/app_process /system/bin ";File injector=new File(c.getFilesDir(),Build.SUPPORTED_ABIS[0].equals("arm64-v8a")?"injector-arm64-17.24.3":"injector-17.24.3");
    try(FileOutputStream live=c.openFileOutput("last-run.txt",Context.MODE_PRIVATE)){
     int attempt=0;while(true){if(bot&&!request.active(generation,globalStop))break;last=null;File workerStop=bot?new File(c.getFilesDir(),"worker-stop-"+generation+"-"+(attempt++)):globalStop;String command;
      if(mode.equals("read")||mode.equals("trucks"))command=prefix+(mode.equals("read")?"dev.codex.lastzhelper.StateProbe ":"dev.codex.lastzhelper.TruckProbe ")+q(cache.getPath());
      else if(mode.equals("world")||mode.equals("base")||mode.equals("roundtrip"))command=prefix+"dev.codex.lastzhelper.ControlProbe "+q(mode)+" "+q(cache.getPath())+" "+q(injector.getPath())+" "+q(agent.getPath())+" "+q(workerStop.getPath());
      else command=prefix+(mode.equals("maintenance-enroll")||bot?"dev.codex.lastzhelper.RotationController ":mode.startsWith("maintenance-")?"dev.codex.lastzhelper.MaintenanceController ":"dev.codex.lastzhelper.AutomationController ")+q(mode)+" "+q(c.getFilesDir().getPath())+" "+q(injector.getPath())+" "+q(agent.getPath())+" "+q(workerStop.getPath())+" "+q(options.toString())+" "+android.os.Process.myPid();
      p=new ProcessBuilder("su","-c",command).redirectErrorStream(true).start();p.getOutputStream().close();final java.lang.Process child=p;final java.util.concurrent.atomic.AtomicLong heartbeat=new java.util.concurrent.atomic.AtomicLong(android.os.SystemClock.elapsedRealtime());final java.util.concurrent.atomic.AtomicBoolean monitored=new java.util.concurrent.atomic.AtomicBoolean(true),stalled=new java.util.concurrent.atomic.AtomicBoolean(false),forced=new java.util.concurrent.atomic.AtomicBoolean(false);
      Thread watch=null;if(bot){watch=new Thread(()->{try{while(monitored.get()&&child.isAlive()){long gap=android.os.SystemClock.elapsedRealtime()-heartbeat.get();if(gap>RecoveryPolicy.STALL_LIMIT){stalled.set(true);workerStop.createNewFile();publish("Recovering","Worker stopped reporting progress; requesting detach before recovery.");long end=android.os.SystemClock.elapsedRealtime()+RecoveryPolicy.DETACH_LIMIT;while(monitored.get()&&child.isAlive()&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(200);if(monitored.get()&&child.isAlive()){forced.set(true);request.finish(generation);child.destroy();try{child.getInputStream().close();}catch(Exception ignored){}}return;}Thread.sleep(1000);}}catch(InterruptedException ignored){}catch(Exception e){if(monitored.get()){forced.set(true);try{request.finish(generation);}catch(Exception ignored){}}}},"LastZ-watchdog");watch.setDaemon(true);watch.start();}
      String accountLabel="";try(BufferedReader reader=new BufferedReader(new InputStreamReader(child.getInputStream(),"UTF-8"))){String line;while((line=reader.readLine())!=null){RunLog.append(text,line,bot||mode.equals("maintenance-enroll"),live);try{JSONObject o=new JSONObject(line);String event=o.optString("event");if(event.equals("rotation-progress")||event.equals("maintenance-progress")||event.equals("maintenance-result")||event.equals("result"))heartbeat.set(android.os.SystemClock.elapsedRealtime());if(event.equals("progress")&&o.has("accountUid")&&o.optString("message").startsWith("Using active account:"))accountLabel=o.getString("message")+"\n";
        if(event.equals("rotation-progress")){awake.renew(6*60*60*1000L);String stage=o.optString("stage");publish(stage.equals("retrying")?"Retrying":stage.equals("restarting")?"Restarting game":stage.equals("reconciling")?"Reconciling":stage.equals("waiting")?"Waiting":stage.equals("needs-attention")||stage.equals("deferred")?"Needs attention":"Running",o.optString("message")+(o.optBoolean("dryRun")?"\nPreview/setup: no claims":""));}
        if(event.equals("maintenance-progress"))publish("Running",accountLabel+o.optString("message")+(o.optBoolean("dryRun")?"\nPreview: no claims":""));
        if(event.equals("progress"))publish("Running",accountLabel+o.optString("message")+"\nScanned "+o.optInt("scanned")+" · Sent "+o.optInt("shared")+" · Attacks "+o.optInt("attacked")+(o.optBoolean("dryRun")?" · Preview":""));if(event.equals("alert")||event.equals("result"))last=o;
       }catch(org.json.JSONException ignored){}}}finally{monitored.set(false);if(watch!=null)watch.interrupt();}
      code=child.waitFor();if(bot&&last!=null)workerStop.delete();forcedAbort=forced.get();boolean unexpected=last==null&&code!=0;boolean cleanStall=stalled.get()&&!forcedAbort&&last!=null&&last.optBoolean("stopped");
      if(!bot||forcedAbort||!(unexpected||cleanStall)||!request.active(generation,globalStop))break;
      if(!request.restart(generation,globalStop)){RunLog.append(text,"Worker restart limit reached; run needs attention",true,live);break;}
      options.put("restartingWorker",true);publish("Recovering","Worker ended; checking exclusive ownership, previous game and pending operations before recovery.");long until=android.os.SystemClock.elapsedRealtime()+RecoveryPolicy.delay(Math.min(attempt-1,2));while(android.os.SystemClock.elapsedRealtime()<until){if(!request.active(generation,globalStop))break;Thread.sleep(100);}if(!request.active(generation,globalStop))break;
     }
    }
   }catch(Exception e){text.append(e.toString());}finally{if(p!=null&&p.isAlive())p.destroy();if(awake!=null)awake.close();if(bot)try{request.finish(generation);}catch(Exception e){text.append("\nCannot finalize run request: "+e);}busy=false;}
   String output=text.toString();try(FileOutputStream f=c.openFileOutput("last-run.txt",Context.MODE_PRIVATE)){f.write(output.getBytes("UTF-8"));}catch(Exception ignored){}
   if(globalStop.exists())publish("Stopped","Stopped. Progress and histories are saved; recovery cancelled.");
   else if(forcedAbort)publish("Needs attention","Worker did not confirm detach. Recovery stopped; pending attempts remain protected.");
   else if(last!=null&&(last.optString("event").equals("alert")||last.optBoolean("targetFound")))publish("Target found","A matching truck is open in Last Z. The run has stopped.");
   else if(last!=null&&last.optBoolean("stopped"))publish("Stopped","Stopped. Progress and histories are saved.");
   else if(last!=null&&last.optBoolean("rotation"))publish(last.optBoolean("ok")?(last.optBoolean("needsAttention")?"Needs attention":"Finished"):"Needs attention",last.optBoolean("ok")?last.optString("message"):last.optString("error"));
   else if(last!=null&&last.has("maintenance")){JSONArray rows=last.optJSONArray("maintenance");StringBuilder message=new StringBuilder();String label="Finished";for(int n=0;rows!=null&&n<rows.length();n++){JSONObject row=rows.optJSONObject(n);if(row==null)continue;if(message.length()>0)message.append("\n");message.append(row.optString("reason"));String outcome=row.optString("outcome");if(outcome.equals("UNCERTAIN"))label="Needs review";else if(outcome.equals("FAILED"))label="Stopped with error";else if(outcome.equals("BLOCKED")&&label.equals("Finished"))label="Blocked";}publish(label,message.toString());}
   else if(code==0)publish("Finished",last==null?output:"Scanned "+last.optInt("scanned")+". Sent: "+last.optInt("shared")+". Attacks: "+last.optInt("attacked")+". Preview matches: "+last.optInt("planned")+"."+(last.optBoolean("dryRun")?" No messages or attacks sent.":""));
   else publish("Needs attention",last==null?"Worker ended unexpectedly (exit "+code+"). Progress and pending attempts are preserved.\n"+output:last.optString("error",last.toString()));
  },"LastZ-run").start();
 }
 static void stop(Context c){try{new File(c.getFilesDir(),"stop-request").createNewFile();new RunRequest(c.getFilesDir()).stop();publish(busy?"Stopping":"Stopped",busy?"Waiting for the current input to release and detach; retries cancelled.":"No active run.");}catch(Exception e){publish("Error",e.toString());}}
}
